package org.ouyalibre.tv;

import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public final class IptvActivity extends Activity {
 private IptvStore store;private IptvStore.Entry selected,pendingFile;private IptvCatalog catalog;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler handler=new Handler();private Future<?> task;
 private TextView title,status;private LinearLayout actions,manage;private ListView list;private ArrayAdapter<String> adapter;
 private final List<String> rows=new ArrayList<String>();private List<IptvStore.Entry> entries=new ArrayList<IptvStore.Entry>();private List<IptvCatalog.Channel> channels=new ArrayList<IptvCatalog.Channel>();private Set<String> favorites=new HashSet<String>();
 private String group=null,query="";private boolean onlyFavorites=false,busy=false,closed=false;private int generation=0;private static final int PICK=40;
 public void onCreate(Bundle b){super.onCreate(b);store=new IptvStore(this);store.migrate(new Store(this));LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,16,24,16);root.setBackgroundColor(Ui.BG);title=Ui.text(this,"TV / IPTV",25);root.addView(title);actions=new LinearLayout(this);root.addView(actions);manage=new LinearLayout(this);root.addView(manage);status=Ui.text(this,"",16);root.addView(status);list=new ListView(this);list.setSelector(Ui.shape(0xff196a60));list.setDividerHeight(4);adapter=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,rows){public View getView(int p,View v,ViewGroup parent){TextView t=(TextView)super.getView(p,v,parent);t.setTextColor(Ui.TEXT);t.setTextSize(19);t.setMaxLines(3);t.setPadding(16,12,16,12);return t;}};list.setAdapter(adapter);list.setOnItemClickListener(new AdapterView.OnItemClickListener(){public void onItemClick(AdapterView<?> a,View v,int p,long id){if(busy)return;if(selected==null)load(entries.get(p),false,null);else channel(channels.get(p));}});root.addView(list,new LinearLayout.LayoutParams(-1,0,1));root.addView(Ui.text(this,Texts.get("O: elegir · A: volver · Cada lista conserva sus canales y favoritos por separado"),14));setContentView(root);home();if(b!=null){String id=b.getString("playlist");for(IptvStore.Entry e:store.entries())if(e.id.equals(id)){group=b.getString("group");query=b.getString("query","");onlyFavorites=b.getBoolean("favorites");load(e,false,null);break;}}}
 private void button(LinearLayout row,String text,final Runnable action){Button b=Ui.button(this,text,new View.OnClickListener(){public void onClick(View v){if(!busy)action.run();}});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,Ui.dp(this,48),1);p.setMargins(3,3,3,3);row.addView(b,p);}
 private void controls(){actions.removeAllViews();manage.removeAllViews();if(selected==null){button(actions,Texts.get("Añadir URL"),new Runnable(){public void run(){addUrl();}});button(actions,Texts.get("Importar archivo"),new Runnable(){public void run(){pickMethod(null);}});button(actions,Texts.get("Volver"),new Runnable(){public void run(){finish();}});}else{button(actions,Texts.get("Mis listas"),new Runnable(){public void run(){home();}});button(actions,Texts.get("Grupos"),new Runnable(){public void run(){groups();}});button(actions,Texts.get("Buscar canal"),new Runnable(){public void run(){Ui.keyboard(IptvActivity.this,Texts.get("Buscar solo en ")+selected.name,query,new Ui.Input(){public void done(String s){query=s;render();}});}});button(actions,onlyFavorites?Texts.get("Ver todos"):Texts.get("Favoritos"),new Runnable(){public void run(){onlyFavorites=!onlyFavorites;render();}});button(manage,Texts.get("Actualizar"),new Runnable(){public void run(){if(selected.remote()||selected.origin.startsWith("file:"))load(selected,true,null);else pickMethod(selected);}});button(manage,Texts.get("Renombrar"),new Runnable(){public void run(){rename();}});button(manage,Texts.get("Canales ocultos"),new Runnable(){public void run(){hiddenChannels();}});button(manage,Texts.get("Eliminar lista"),new Runnable(){public void run(){remove();}});}enabled(!busy);}
 private void enabled(boolean value){for(LinearLayout row:new LinearLayout[]{actions,manage})for(int i=0;i<row.getChildCount();i++)row.getChildAt(i).setEnabled(value);list.setEnabled(value);}
 private void home(){generation++;if(task!=null)task.cancel(true);busy=false;selected=null;catalog=null;group=null;query="";onlyFavorites=false;entries=store.entries();rows.clear();for(IptvStore.Entry e:entries)rows.add(e.name+"\n"+(e.updated>0?e.count+Texts.get(" canales · ")+new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.US).format(new Date(e.updated)):Texts.get("Pendiente de importar"))+" · "+(e.remote()?"URL":Texts.get("Archivo")));adapter.notifyDataSetChanged();title.setText(Texts.get("TV / IPTV · Mis listas"));status.setText(entries.isEmpty()?Texts.get("Añade una URL o importa un archivo M3U. Sus canales no se mezclarán con otras listas."):entries.size()+Texts.get(" listas independientes. Elige una para ver sus canales."));controls();actions.getChildAt(0).requestFocus();}
 private void render(){if(selected==null||catalog==null)return;favorites=store.favorites(selected);channels=catalog.filter(group,query,favorites,onlyFavorites);Set<String> hidden=store.hidden(selected);for(Iterator<IptvCatalog.Channel> it=channels.iterator();it.hasNext();)if(hidden.contains(it.next().key()))it.remove();rows.clear();for(IptvCatalog.Channel c:channels)rows.add((favorites.contains(c.key())?"★ ":"")+c.title+"\n"+c.group);adapter.notifyDataSetChanged();title.setText("TV / IPTV · "+selected.name);status.setText(channels.size()+" / "+catalog.channels.size()+Texts.get(" canales · ")+(group==null?Texts.get("Todos los grupos"):group)+(query.length()>0?" · «"+query+"»":"")+(onlyFavorites?Texts.get(" · Favoritos"):"")+(catalog.skipped>0?"\n"+catalog.skipped+Texts.get(" entradas omitidas por dirección no compatible"):""));controls();}
 private void load(final IptvStore.Entry e,final boolean refresh,final Uri replacement){if(busy)return;final int gen=++generation;if(selected==null||!selected.id.equals(e.id)){group=null;query="";onlyFavorites=false;}selected=e;catalog=null;busy=true;rows.clear();adapter.notifyDataSetChanged();title.setText("TV / IPTV · "+e.name);status.setText(refresh||!store.cached(e)?Texts.get("Importando lista…"):Texts.get("Abriendo copia guardada…"));controls();task=worker.submit(new Runnable(){public void run(){IptvCatalog result=null;String failure=null;try{result=refresh||!store.cached(e)?store.refresh(e,replacement):store.cachedCatalog(e);}catch(Exception x){failure=err(x);}final IptvCatalog data=result;final String error=failure;handler.post(new Runnable(){public void run(){if(closed||gen!=generation)return;busy=false;if(data!=null){catalog=data;render();if(list.getCount()>0)list.requestFocus();}else{controls();status.setText(Texts.get("No se pudo importar. La copia anterior, si existe, se conserva."));message(Texts.get("Lista no disponible"),error);}}});}});}
 private void addUrl(){Ui.keyboard(this,Texts.get("Nombre de la lista"),Texts.get("Lista ")+(store.entries().size()+1),new Ui.Input(){public void done(final String name){Ui.keyboard(IptvActivity.this,Texts.get("URL HTTP/HTTPS de la lista M3U"),"https://",new Ui.Input(){public void done(String u){try{IptvCatalog.http(u);IptvStore.Entry e=store.add(name,u);load(e,true,null);}catch(Exception x){message(Texts.get("No se pudo añadir"),err(x));}}});}});}
 private void pickMethod(final IptvStore.Entry replace){AlertDialog d=new AlertDialog.Builder(this).setTitle(Texts.get("Importar M3U")).setItems(new String[]{"Elegir con explorador de archivos",Texts.get("Buscar en memoria / USB")},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int p){if(p==0)systemPicker(replace);else roots(replace);}}).setNegativeButton(Texts.get("Cancelar"),null).create();d.show();Ui.controller(d);}
 private void systemPicker(IptvStore.Entry replace){pendingFile=replace;Intent intent=new Intent(Intent.ACTION_GET_CONTENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivityForResult(intent,PICK);}catch(ActivityNotFoundException e){roots(replace);}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK&&result==RESULT_OK&&data!=null&&data.getData()!=null)importFile(data.getData(),pendingFile);pendingFile=null;}
 private void roots(final IptvStore.Entry replace){final List<File> paths=new ArrayList<File>();for(String p:new String[]{"/sdcard","/mnt/usbdrive","/storage"}){File f=new File(p);if(f.isDirectory()&&f.canRead())paths.add(f);}if(paths.isEmpty()){message(Texts.get("Archivos"),Texts.get("No hay memoria o USB accesible."));return;}String[] labels=new String[paths.size()];for(int i=0;i<labels.length;i++)labels[i]=paths.get(i).getPath();AlertDialog d=new AlertDialog.Builder(this).setTitle("Memoria / USB").setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){folder(paths.get(i),paths.get(i),replace);}}).setNegativeButton(Texts.get("Cancelar"),null).create();d.show();Ui.controller(d);}
 private void folder(final File root,final File folder,final IptvStore.Entry replace){File[] all=folder.listFiles();if(all==null){message(Texts.get("Archivos"),Texts.get("No se puede leer esta carpeta."));return;}final List<File> files=new ArrayList<File>();for(File f:all){String n=f.getName().toLowerCase(Locale.US);if(!n.startsWith(".")&&f.canRead()&&(f.isDirectory()||n.endsWith(".m3u")||n.endsWith(".m3u8")))files.add(f);}Collections.sort(files,new Comparator<File>(){public int compare(File a,File b){if(a.isDirectory()!=b.isDirectory())return a.isDirectory()?-1:1;return a.getName().compareToIgnoreCase(b.getName());}});if(files.size()>1000){message(Texts.get("Archivos"),Texts.get("Demasiados archivos en esta carpeta. Usa el explorador de archivos del sistema."));return;}final boolean up=!folder.equals(root);String[] labels=new String[files.size()+(up?1:0)];int index=0;if(up)labels[index++]=Texts.get("[Subir carpeta]");for(File f:files)labels[index++]=(f.isDirectory()?Texts.get("[Carpeta] "):"")+f.getName();AlertDialog d=new AlertDialog.Builder(this).setTitle(folder.getPath()).setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){if(up&&i==0){folder(root,folder.getParentFile(),replace);return;}File f=files.get(i-(up?1:0));if(f.isDirectory())folder(root,f,replace);else importFile(Uri.fromFile(f),replace);}}).setNegativeButton(Texts.get("Cancelar"),null).create();d.show();Ui.controller(d);}
 private void importFile(final Uri uri,final IptvStore.Entry replace){if(replace!=null){load(replace,true,uri);return;}Ui.keyboard(this,Texts.get("Nombre para este archivo M3U"),Texts.get("Lista ")+(store.entries().size()+1),new Ui.Input(){public void done(String name){try{IptvStore.Entry e=store.add(name,uri.toString());load(e,true,uri);}catch(Exception x){message(Texts.get("No se pudo importar"),err(x));}}});}
 private void groups(){if(catalog==null)return;final List<String> g=catalog.groups();String[] labels=new String[g.size()+1];labels[0]=Texts.get("Todos los grupos");for(int i=0;i<g.size();i++)labels[i+1]=g.get(i);AlertDialog d=new AlertDialog.Builder(this).setTitle(Texts.get("Grupos de ")+selected.name).setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){group=i==0?null:g.get(i-1);render();}}).setNegativeButton(Texts.get("Volver"),null).create();d.show();Ui.controller(d);}
 private void rename(){final IptvStore.Entry e=selected;Ui.keyboard(this,Texts.get("Nombre de esta lista"),e.name,new Ui.Input(){public void done(String s){try{store.rename(e,s);if(catalog!=null)render();else controls();}catch(Exception x){message(Texts.get("Nombre no válido"),err(x));}}});}
 private void remove(){final IptvStore.Entry e=selected;AlertDialog d=new AlertDialog.Builder(this).setTitle(Texts.get("Eliminar «")+e.name+"»").setMessage(Texts.get("Se eliminarán su copia guardada y sus favoritos. Las demás listas y el archivo original se conservan.")).setPositiveButton(Texts.get("Eliminar"),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{store.remove(e);home();}catch(Exception x){message(Texts.get("No se pudo eliminar"),err(x));}}}).setNegativeButton(Texts.get("Cancelar"),null).create();d.show();Ui.controller(d);}
 private void channel(final IptvCatalog.Channel c){final IptvStore.Entry e=selected;AlertDialog d=new AlertDialog.Builder(this).setTitle(c.title).setMessage(e.name+Texts.get("\nGrupo: ")+c.group+Texts.get("\nLa calidad depende de la señal y del códec. No se convierte el canal a 1080p.")).setPositiveButton(Texts.get("Reproducir"),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{Item item=new Item("IPTV · "+e.id,c.key(),c.title,c.group,"",c.url);Intent intent=new Intent(IptvActivity.this,PlayerActivity.class);intent.putExtra("item",item.json().toString());intent.putExtra("stream",c.url);intent.putExtra("live",true);intent.putExtra("iptvList",e.id);intent.putExtra("iptvChannel",c.key());startActivity(intent);}catch(Exception x){message(Texts.get("No se pudo abrir"),err(x));}}}).setNeutralButton("Opciones",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){channelOptions(e,c);}}).setNegativeButton(Texts.get("Volver"),null).create();d.show();Ui.controller(d);}
 private void channelOptions(final IptvStore.Entry e,final IptvCatalog.Channel c){AlertDialog d=new AlertDialog.Builder(this).setTitle(c.title).setItems(new String[]{favorites.contains(c.key())?Texts.get("Quitar favorito"):Texts.get("Guardar favorito"),Texts.get("Ocultar canal (sin modificar M3U)")},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){try{if(i==0)store.toggle(e,c);else{store.setHidden(e,c.key(),true);Toast.makeText(IptvActivity.this,Texts.get("Canal oculto. Puedes restaurarlo en Canales ocultos."),Toast.LENGTH_LONG).show();}render();}catch(Exception x){message(Texts.get("No se pudo guardar"),err(x));}}}).setNegativeButton(Texts.get("Cancelar"),null).create();d.show();Ui.controller(d);}
 private void hiddenChannels(){if(catalog==null)return;final IptvStore.Entry e=selected;Set<String> hidden=store.hidden(e);final List<IptvCatalog.Channel> values=new ArrayList<IptvCatalog.Channel>();for(IptvCatalog.Channel c:catalog.channels)if(hidden.contains(c.key()))values.add(c);String[] labels=new String[values.size()];for(int i=0;i<labels.length;i++)labels[i]=Texts.get("Mostrar: ")+values.get(i).title;AlertDialog d=new AlertDialog.Builder(this).setTitle(Texts.get("Canales ocultos de ")+e.name+" ("+values.size()+")").setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){try{store.setHidden(e,values.get(i).key(),false);render();}catch(Exception x){message(Texts.get("No se pudo restaurar"),err(x));}}}).setPositiveButton(Texts.get("Mostrar todos"),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{store.restoreAll(e);render();}catch(Exception x){message(Texts.get("No se pudo restaurar"),err(x));}}}).setNegativeButton(Texts.get("Volver"),null).create();d.show();Ui.controller(d);}
 protected void onResume(){super.onResume();if(selected!=null&&catalog!=null&&!busy)render();}
 private void message(String heading,String text){AlertDialog d=new AlertDialog.Builder(this).setTitle(heading).setMessage(text).setPositiveButton(Texts.get("Aceptar"),null).create();d.show();Ui.controller(d);}
 private static String err(Exception e){return e.getMessage()==null?Texts.get("No se pudo completar la operación"):e.getMessage();}
 public void onBackPressed(){if(selected!=null)home();else super.onBackPressed();}
 public boolean dispatchKeyEvent(KeyEvent e){int c=e.getKeyCode();if(c==KeyEvent.KEYCODE_BUTTON_A)return super.dispatchKeyEvent(new KeyEvent(e.getDownTime(),e.getEventTime(),e.getAction(),KeyEvent.KEYCODE_DPAD_CENTER,0));if(c==KeyEvent.KEYCODE_BUTTON_B){if(e.getAction()==KeyEvent.ACTION_UP)onBackPressed();return true;}return super.dispatchKeyEvent(e);}
 protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(selected!=null)b.putString("playlist",selected.id);b.putString("group",group);b.putString("query",query);b.putBoolean("favorites",onlyFavorites);}
 protected void onDestroy(){closed=true;generation++;if(task!=null)task.cancel(true);worker.shutdownNow();handler.removeCallbacksAndMessages(null);super.onDestroy();}
}
